	var width = ((j) => j.length ? j : $('#mf_checkcombobox1_itemTable_1_checkbox'))($('#checkcombobox1_itemTable_1_checkbox')).width() + ((j) => j.length ? j : $('#mf_checkcombobox1_itemTable_1 label'))($('#checkcombobox1_itemTable_1 label')).width();
